class Solution {
    void dfs(TreeNode* a, TreeNode* b, int level) {
        if (!a || !b) return;
        if (level % 2 == 1) {
            int tmp = a->val;
            a->val = b->val;
            b->val = tmp;
        }
        dfs(a->left, b->right, level + 1);
        dfs(a->right, b->left, level + 1);
    }
public:
    TreeNode* reverseOddLevels(TreeNode* root) {
        if (!root) return root;
        dfs(root->left, root->right, 1);
        return root;
    }
};
